#include <bits/stdc++.h>
using namespace std;

#define rep(i, x) for(int i = 0; i < (x); i++)

int main() {
	int n, m;
	cin >> n >> m;
	vector<int> a(m);
	rep(i, m) cin >> a[i];
	vector<string> s(n);
	rep(i, n) cin >> s[i];
	vector<int> now_sc(n);
	rep(i, n) now_sc[i] = i + 1;
	rep(i, n) rep(j, m) if(s[i][j] == 'o') now_sc[i] += a[j];
	int mx = *max_element(now_sc.begin(), now_sc.end());
	rep(i, n) {
		vector<int> nokori;
		rep(j, m) if(s[i][j] == 'x') nokori.push_back(a[j]);
		sort(nokori.rbegin(), nokori.rend());
		int ans = 0;
		while(now_sc[i] < mx) {
			now_sc[i] += nokori[ans++];
		}
		cout << ans << endl;
	}
}
